WITH enriched AS (SELECT *, FIRST_VALUE(country) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at, id) AS event_seq, FIRST_VALUE(browser, TRUE) OVER w_part AS first_known_browser, LAST_VALUE(country, TRUE) OVER (PARTITION BY device, browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, ROW_NUMBER() OVER (ORDER BY started_at, id) AS seq_no FROM sessions WINDOW w_part AS (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, s.first_known_country, s.event_seq, s.first_known_browser, s.last_known_country, (SELECT AVG(x.amount) FROM orders x WHERE x.customer_id = s.customer_id) AS avg_order_amount FROM enriched s;
